/**
 * 第 1 关 · 深拷贝：连循环引用一起拷贝
 */
function deepClone(value, seen = new WeakMap()) {
  if (value === null || typeof value !== 'object') return value
  if (seen.has(value)) return seen.get(value)

  if (value instanceof Date) return new Date(value.getTime())

  if (value instanceof Map) {
    const copy = new Map()
    seen.set(value, copy)
    for (const [k, v] of value) copy.set(k, deepClone(v, seen))
    return copy
  }

  if (value instanceof Set) {
    const copy = new Set()
    seen.set(value, copy)
    for (const v of value) copy.add(deepClone(v, seen))
    return copy
  }

  const copy = Array.isArray(value) ? [] : {}
  seen.set(value, copy)
  for (const key of Object.keys(value)) {
    copy[key] = deepClone(value[key], seen)
  }
  return copy
}

stages.test:
{
  check('Date 复制成新的 Date，时间相同', () => {
    const d = new Date(1700000000000)
    const e = deepClone(d)
    ok(e instanceof Date && e !== d)
    same(e.getTime(), d.getTime())
  })
  check('Map 里的嵌套对象也被深拷贝', () => {
    const m = new Map([['k', { v: 1 }]])
    const n = deepClone(m)
    n.get('k').v = 9
    same(m.get('k').v, 1)
  })
  check('Set 里的对象也被深拷贝', () => {
    const item = { v: 1 }
    const s = new Set([item])
    const t = deepClone(s)
    ok(t instanceof Set && t !== s)
    const cloned = [...t][0]
    cloned.v = 9
    same(item.v, 1)
  })
  check('函数原样传递（函数没有「深拷贝」语义）', () => {
    const fn = () => 1
    const src = { fn }
    const copy = deepClone(src)
    same(copy.fn, fn)
  })
}

