    let n = 0
    const fn = () => { n++ }
    b5.once('w', fn)
    b5.off('w', fn)
    same(b5.emit('w'), false)
    same(n, 0)
  })
  check('once 的参数原样透传', () => {
    const b11 = new EventEmitter()
